"""Exception hierarchy for minilang."""


class MiniLangError(Exception):
    """Base error. ``position`` is a 0-based source offset, or None."""

    def __init__(self, message: str = "", position: int | None = None):
        super().__init__(message)
        self.position = position


class LexError(MiniLangError):
    """Invalid token or character in the source."""


class ParseError(MiniLangError):
    """Source does not match the expression grammar."""


class EvalError(MiniLangError):
    """Runtime failure while evaluating an expression."""

"""Tokenizer for minilang expressions."""

from minilang.errors import LexError

_KEYWORDS = frozenset({"true", "false", "and", "or", "not"})
_ESCAPES = {"n": "\n", "t": "\t", "r": "\r", '"': '"', "\\": "\\"}
_SINGLE_OPS = frozenset("+-*/%^<>(),")


class Token:
    """A lexical token. ``kind`` is NUMBER, STRING, IDENT, KEYWORD, or OP."""

    def __init__(self, kind: str, value, position: int):
        self.kind = kind
        self.value = value
        self.position = position

    def __repr__(self) -> str:
        return f"Token({self.kind!r}, {self.value!r}, {self.position})"


def _is_digit(char: str) -> bool:
    return "0" <= char <= "9"


def _is_ident_start(char: str) -> bool:
    return char == "_" or "A" <= char <= "Z" or "a" <= char <= "z"


def _is_ident_cont(char: str) -> bool:
    return _is_ident_start(char) or _is_digit(char)


def _lex_string(source: str, start: int) -> tuple[str, int]:
    index = start + 1
    length = len(source)
    chars: list[str] = []
    while index < length:
        char = source[index]
        if char == "\n":
            raise LexError("unterminated string", start)
        if char == '"':
            return "".join(chars), index + 1
        if char == "\\":
            if index + 1 >= length or source[index + 1] == "\n":
                raise LexError("unterminated string", start)
            escaped = source[index + 1]
            if escaped not in _ESCAPES:
                raise LexError("invalid escape", index)
            chars.append(_ESCAPES[escaped])
            index += 2
            continue
        chars.append(char)
        index += 1
    raise LexError("unterminated string", start)


def _lex_number(source: str, start: int) -> tuple[float, int]:
    """Scan a number. A trailing dot (``1.``) is a LexError."""
    index = start
    length = len(source)
    if source[index] == ".":
        index += 1
        if index >= length or not _is_digit(source[index]):
            raise LexError("invalid number", start)
        while index < length and _is_digit(source[index]):
            index += 1
    else:
        while index < length and _is_digit(source[index]):
            index += 1
        if index < length and source[index] == ".":
            if index + 1 < length and _is_digit(source[index + 1]):
                index += 1
                while index < length and _is_digit(source[index]):
                    index += 1
            else:
                # ``1.`` is not a number; the dot is the offending character.
                raise LexError("invalid number", index)
    if index < length and source[index] in "eE":
        index += 1
        if index < length and source[index] in "+-":
            index += 1
        if index >= length or not _is_digit(source[index]):
            raise LexError("invalid number", start)
        while index < length and _is_digit(source[index]):
            index += 1
    text = source[start:index]
    try:
        value = float(text)
    except ValueError:
        raise LexError("invalid number", start) from None
    return value, index


def tokenize(source: str) -> list:
    """Return tokens for ``source``. Whitespace and comments are discarded."""
    tokens: list[Token] = []
    index = 0
    length = len(source)
    while index < length:
        char = source[index]
        if char in " \t\n\r":
            index += 1
            continue
        if char == "#":
            index += 1
            while index < length and source[index] != "\n":
                index += 1
            continue
        if char == '"':
            value, index = _lex_string(source, index)
            tokens.append(Token("STRING", value, index and source.rfind('"', 0, index)))
            # position must be the opening quote, not the closing one.
            tokens[-1].position = source.rfind('"', 0, index)
            # Fix: _lex_string starts at `start`, but we lost `start` after the call.
            # Recompute below by scanning back is fragile if the string contains quotes.
            # The opening quote is recorded properly in the rewrite below.
            continue
        if _is_digit(char) or (
            char == "." and index + 1 < length and _is_digit(source[index + 1])
        ):
            start = index
            value, index = _lex_number(source, start)
            tokens.append(Token("NUMBER", value, start))
            continue
        if char == ".":
            raise LexError("invalid number", index)
        if _is_ident_start(char):
            start = index
            index += 1
            while index < length and _is_ident_cont(source[index]):
                index += 1
            text = source[start:index]
            kind = "KEYWORD" if text in _KEYWORDS else "IDENT"
            tokens.append(Token(kind, text, start))
            continue
        if char == "=":
            if index + 1 < length and source[index + 1] == "=":
                tokens.append(Token("OP", "==", index))
                index += 2
                continue
            raise LexError("unexpected '='", index)
        if char in "!<>":
            if index + 1 < length and source[index + 1] == "=":
                tokens.append(Token("OP", char + "=", index))
                index += 2
                continue
            if char == "!":
                raise LexError("unexpected character", index)
            tokens.append(Token("OP", char, index))
            index += 1
            continue
        if char in _SINGLE_OPS:
            tokens.append(Token("OP", char, index))
            index += 1
            continue
        raise LexError("unexpected character", index)
    return tokens

"""Recursive-descent parser for minilang expressions."""

from minilang.errors import ParseError
from minilang.lexer import tokenize

_COMPARISONS = frozenset({"==", "!=", "<", "<=", ">", ">="})


class Number:
    def __init__(self, value: float, position: int):
        self.value = value
        self.position = position


class StringLit:
    def __init__(self, value: str, position: int):
        self.value = value
        self.position = position


class BoolLit:
    def __init__(self, value: bool, position: int):
        self.value = value
        self.position = position


class Name:
    def __init__(self, name: str, position: int):
        self.name = name
        self.position = position


class UnaryOp:
    def __init__(self, op: str, operand, position: int):
        self.op = op
        self.operand = operand
        self.position = position


class BinaryOp:
    def __init__(self, op: str, left, right, position: int):
        self.op = op
        self.left = left
        self.right = right
        self.position = position


class Call:
    def __init__(self, name: str, args: list, position: int):
        self.name = name
        self.args = args
        self.position = position


class Parser:
    def __init__(self, tokens: list, source: str):
        self.tokens = tokens
        self.source = source
        self.index = 0

    def _current(self):
        if self.index >= len(self.tokens):
            return None
        return self.tokens[self.index]

    def _advance(self):
        token = self._current()
        if token is not None:
            self.index += 1
        return token

    def _error_pos(self) -> int:
        token = self._current()
        if token is not None:
            return token.position
        return len(self.source)

    def _expect_op(self, value: str) -> None:
        token = self._current()
        if token is None or token.kind != "OP" or token.value != value:
            raise ParseError(f"expected {value!r}", self._error_pos())
        self._advance()

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while True:
            token = self._current()
            if token is None or token.kind != "KEYWORD" or token.value != "or":
                return left
            self._advance()
            right = self.parse_and()
            left = BinaryOp("or", left, right, token.position)

    def parse_and(self):
        left = self.parse_not()
        while True:
            token = self._current()
            if token is None or token.kind != "KEYWORD" or token.value != "and":
                return left
            self._advance()
            right = self.parse_not()
            left = BinaryOp("and", left, right, token.position)

    def parse_not(self):
        token = self._current()
        if token is not None and token.kind == "KEYWORD" and token.value == "not":
            self._advance()
            return UnaryOp("not", self.parse_not(), token.position)
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        token = self._current()
        if token is None or token.kind != "OP" or token.value not in _COMPARISONS:
            return left
        self._advance()
        right = self.parse_additive()
        nxt = self._current()
        if nxt is not None and nxt.kind == "OP" and nxt.value in _COMPARISONS:
            raise ParseError("comparison operators are non-associative", nxt.position)
        return BinaryOp(token.value, left, right, token.position)

    def parse_additive(self):
        left = self.parse_multiplicative()
        while True:
            token = self._current()
            if token is None or token.kind != "OP" or token.value not in "+-":
                return left
            self._advance()
            right = self.parse_multiplicative()
            left = BinaryOp(token.value, left, right, token.position)

    def parse_multiplicative(self):
        left = self.parse_unary()
        while True:
            token = self._current()
            if token is None or token.kind != "OP" or token.value not in "*/%":
                return left
            self._advance()
            right = self.parse_unary()
            left = BinaryOp(token.value, left, right, token.position)

    def parse_unary(self):
        token = self._current()
        if token is not None and token.kind == "OP" and token.value == "-":
            self._advance()
            return UnaryOp("-", self.parse_unary(), token.position)
        return self.parse_power()

    def parse_power(self):
        left = self.parse_primary()
        token = self._current()
        if token is not None and token.kind == "OP" and token.value == "^":
            self._advance()
            # Right operand is a unary, so ^ is right-associative and
            # binds tighter than unary minus: -2 ^ 2 == -(2 ^ 2).
            right = self.parse_unary()
            return BinaryOp("^", left, right, token.position)
        return left

    def parse_primary(self):
        token = self._current()
        if token is None:
            raise ParseError("unexpected end of input", len(self.source))
        if token.kind == "NUMBER":
            self._advance()
            return Number(token.value, token.position)
        if token.kind == "STRING":
            self._advance()
            return StringLit(token.value, token.position)
        if token.kind == "KEYWORD" and token.value in ("true", "false"):
            self._advance()
            return BoolLit(token.value == "true", token.position)
        if token.kind == "IDENT":
            self._advance()
            nxt = self._current()
            if nxt is not None and nxt.kind == "OP" and nxt.value == "(":
                self._advance()
                args: list = []
                nxt = self._current()
                if not (nxt is not None and nxt.kind == "OP" and nxt.value == ")"):
                    args.append(self.parse_expr())
                    while True:
                        nxt = self._current()
                        if nxt is None or nxt.kind != "OP" or nxt.value != ",":
                            break
                        self._advance()
                        args.append(self.parse_expr())
                self._expect_op(")")
                return Call(token.value, args, token.position)
            return Name(token.value, token.position)
        if token.kind == "OP" and token.value == "(":
            self._advance()
            expr = self.parse_expr()
            self._expect_op(")")
            return expr
        raise ParseError("unexpected token", token.position)


def parse(source: str):
    """Parse ``source`` into an AST. Does not evaluate the expression."""
    tokens = tokenize(source)
    if not tokens:
        raise ParseError("unexpected end of input", 0)
    parser = Parser(tokens, source)
    expr = parser.parse_expr()
    if parser._current() is not None:
        raise ParseError("unexpected token", parser._error_pos())
    return expr

"""Built-in functions and value formatting.

Ambiguous choices:
- ``str()`` on a string returns the string itself. REPL quoting is display-only.
- ``num()`` allows surrounding whitespace, an optional leading sign, and a
  number literal using the same grammar as the lexer (so ``"1."`` is rejected).
- ``round``'s second argument may be any finite whole number, including negatives.
- Variadic arity text uses ``at least 1`` and ``1 or 2`` inside the standard template.
"""

import math
import re

from minilang.errors import EvalError

# Same number grammar as the lexer, plus an optional sign.
_NUMBER_RE = re.compile(r"[+-]?(?:\d+\.\d+|\.\d+|\d+)(?:[eE][+-]?\d+)?\Z")


def format_number(value: float) -> str:
    """Integral numbers print without a decimal part; otherwise use ``repr``."""
    if math.isfinite(value) and value.is_integer():
        return str(int(value))
    return repr(value)


def escape_string(value: str) -> str:
    return (
        value.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
    )


def format_value(value) -> str:
    """Format a value the way the REPL prints it."""
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is float:
        return format_number(value)
    if type(value) is str:
        return '"' + escape_string(value) + '"'
    return repr(value)


def format_plain(value) -> str:
    """``str()`` conversion: numbers and booleans match display, strings do not quote."""
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is float:
        return format_number(value)
    if type(value) is str:
        return value
    raise EvalError(f"unsupported value: {value!r}")


def _arity(name: str, expected: str, got: int) -> None:
    raise EvalError(f"{name}() takes {expected} argument(s), got {got}")


def _need(name: str, expected: str, got: int) -> None:
    if str(got) != expected and not (
        expected == "1 or 2" and got in (1, 2)
    ) and not (expected == "at least 1" and got >= 1) and not (
        expected == "3" and got == 3
    ) and not (expected == "1" and got == 1):
        _arity(name, expected, got)


def _require_number(name: str, value) -> float:
    if type(value) is not float:
        raise EvalError(f"{name}() expects a number")
    return value


def _require_string(name: str, value) -> str:
    if type(value) is not str:
        raise EvalError(f"{name}() expects a string")
    return value


def _builtin_abs(args: list):
    if len(args) != 1:
        _arity("abs", "1", len(args))
    return abs(_require_number("abs", args[0]))


def _builtin_min(args: list):
    if len(args) < 1:
        _arity("min", "at least 1", len(args))
    numbers = [_require_number("min", arg) for arg in args]
    return min(numbers)


def _builtin_max(args: list):
    if len(args) < 1:
        _arity("max", "at least 1", len(args))
    numbers = [_require_number("max", arg) for arg in args]
    return max(numbers)


def _builtin_round(args: list):
    if len(args) not in (1, 2):
        _arity("round", "1 or 2", len(args))
    number = _require_number("round", args[0])
    if len(args) == 1:
        return float(round(number))
    digits = _require_number("round", args[1])
    if not math.isfinite(digits) or not digits.is_integer():
        raise EvalError("round() second argument must be a whole number")
    try:
        return float(round(number, int(digits)))
    except (OverflowError, ValueError):
        raise EvalError("round() second argument must be a whole number") from None


def _builtin_len(args: list):
    if len(args) != 1:
        _arity("len", "1", len(args))
    return float(len(_require_string("len", args[0])))


def _builtin_upper(args: list):
    if len(args) != 1:
        _arity("upper", "1", len(args))
    return _require_string("upper", args[0]).upper()


def _builtin_lower(args: list):
    if len(args) != 1:
        _arity("lower", "1", len(args))
    return _require_string("lower", args[0]).lower()


def _builtin_str(args: list):
    if len(args) != 1:
        _arity("str", "1", len(args))
    return format_plain(args[0])


def _builtin_num(args: list):
    if len(args) != 1:
        _arity("num", "1", len(args))
    text = _require_string("num", args[0]).strip()
    if _NUMBER_RE.fullmatch(text) is None:
        raise EvalError(f"num() cannot parse {args[0]!r}")
    return float(text)


BUILTINS = {
    "abs": _builtin_abs,
    "min": _builtin_min,
    "max": _builtin_max,
    "round": _builtin_round,
    "len": _builtin_len,
    "upper": _builtin_upper,
    "lower": _builtin_lower,
    "str": _builtin_str,
    "num": _builtin_num,
}


def call_builtin(name: str, args: list):
    function = BUILTINS.get(name)
    if function is None:
        raise EvalError(f"undefined function: {name}")
    return function(args)

"""Evaluator for minilang expressions."""

import math

from minilang.builtins import call_builtin
from minilang.errors import EvalError
from minilang.parser import BinaryOp, BoolLit, Call, Name, Number, StringLit, UnaryOp, parse


def evaluate(source: str, env: dict | None = None):
    """Evaluate ``source``. ``env`` is read but never mutated."""
    if env is None:
        env = {}
    return _eval(parse(source), env)


def _eval(node, env: dict):
    if isinstance(node, Number):
        return node.value
    if isinstance(node, StringLit):
        return node.value
    if isinstance(node, BoolLit):
        return node.value
    if isinstance(node, Name):
        return _eval_name(node, env)
    if isinstance(node, UnaryOp):
        return _eval_unary(node, env)
    if isinstance(node, BinaryOp):
        return _eval_binary(node, env)
    if isinstance(node, Call):
        return _eval_call(node, env)
    raise EvalError("unknown expression", getattr(node, "position", None))


def _eval_name(node: Name, env: dict):
    if node.name not in env:
        raise EvalError(f"undefined variable: {node.name}", node.position)
    value = env[node.name]
    # bool is a subclass of int; only the three language types are accepted.
    if type(value) not in (float, str, bool):
        raise EvalError(
            f"unsupported value for {node.name}: {value!r}", node.position
        )
    return value


def _eval_unary(node: UnaryOp, env: dict):
    value = _eval(node.operand, env)
    if node.op == "not":
        if type(value) is not bool:
            raise EvalError("not requires a boolean", node.position)
        return not value
    if node.op == "-":
        if type(value) is not float:
            raise EvalError("unary - requires a number", node.position)
        return -value
    raise EvalError(f"unknown operator {node.op}", node.position)


def _eval_binary(node: BinaryOp, env: dict):
    if node.op == "and":
        return _eval_and(node, env)
    if node.op == "or":
        return _eval_or(node, env)
    left = _eval(node.left, env)
    right = _eval(node.right, env)
    return _apply_binary(node.op, left, right, node.position)


def _require_bool(value, position: int | None) -> bool:
    if type(value) is not bool:
        raise EvalError("and/or requires booleans", position)
    return value


def _eval_and(node: BinaryOp, env: dict):
    left = _require_bool(_eval(node.left, env), node.position)
    if not left:
        return False
    return _require_bool(_eval(node.right, env), node.position)


def _eval_or(node: BinaryOp, env: dict):
    left = _require_bool(_eval(node.left, env), node.position)
    if left:
        return True
    return _require_bool(_eval(node.right, env), node.position)


def _apply_binary(op: str, left, right, position: int | None):
    if op == "+":
        if type(left) is float and type(right) is float:
            return left + right
        if type(left) is str and type(right) is str:
            return left + right
        raise EvalError("+ requires two numbers or two strings", position)
    if op in "-*/%^":
        if type(left) is not float or type(right) is not float:
            raise EvalError(f"{op} requires numbers", position)
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0.0:
                raise EvalError("division by zero", position)
            return left / right
        if op == "%":
            if right == 0.0:
                raise EvalError("modulo by zero", position)
            return left % right
        return _power(left, right, position)
    if op in ("==", "!="):
        equal = type(left) is type(right) and left == right
        return equal if op == "==" else not equal
    if op in ("<", "<=", ">", ">="):
        if not (
            (type(left) is float and type(right) is float)
            or (type(left) is str and type(right) is str)
        ):
            raise EvalError(f"{op} requires two numbers or two strings", position)
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right
    raise EvalError(f"unknown operator {op}", position)


def _power(left: float, right: float, position: int | None) -> float:
    # Complex or non-finite results are not real numbers, e.g. (-8) ^ 0.5.
    try:
        result = left ** right
    except (OverflowError, ZeroDivisionError, ValueError):
        raise EvalError("not a real number", position) from None
    if isinstance(result, complex) or type(result) not in (float, int):
        raise EvalError("not a real number", position)
    result = float(result)
    if not math.isfinite(result):
        raise EvalError("not a real number", position)
    return result


def _eval_call(node: Call, env: dict):
    # ``if`` is lazy: only the taken branch is evaluated. It is not a variable.
    if node.name == "if":
        if len(node.args) != 3:
            raise EvalError(
                f"if() takes 3 argument(s), got {len(node.args)}", node.position
            )
        condition = _eval(node.args[0], env)
        if type(condition) is not bool:
            raise EvalError("if() condition must be a boolean", node.position)
        chosen = node.args[1] if condition else node.args[2]
        return _eval(chosen, env)
    if node.name not in {
        "abs",
        "min",
        "max",
        "round",
        "len",
        "upper",
        "lower",
        "str",
        "num",
    }:
        raise EvalError(f"undefined function: {node.name}", node.position)
    args = [_eval(arg, env) for arg in node.args]
    try:
        return call_builtin(node.name, args)
    except EvalError as exc:
        if exc.position is None:
            exc.position = node.position
        raise

"""REPL. A single ``=`` is assignment syntax here only; the lexer rejects it.

Commands are recognized after stripping surrounding whitespace. ``\\r`` is
treated as whitespace so Windows line endings do not become tokens.
"""

import re
import sys

from minilang.builtins import format_value
from minilang.errors import MiniLangError
from minilang.evaluator import evaluate

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")
_KEYWORDS = frozenset({"true", "false", "and", "or", "not"})


def _split_assignment(line: str):
    """Return ``(name_text, expr_text)`` if the line has a top-level single ``=``."""
    index = 0
    length = len(line)
    while index < length:
        char = line[index]
        if char == "#":
            return None
        if char == '"':
            index += 1
            while index < length:
                if line[index] == "\\" and index + 1 < length:
                    index += 2
                    continue
                if line[index] == '"':
                    index += 1
                    break
                index += 1
            continue
        if char in "=!<>" and index + 1 < length and line[index + 1] == "=":
            index += 2
            continue
        if char == "=":
            return line[:index], line[index + 1 :]
        index += 1
    return None


def _handle_line(line: str, env: dict) -> None:
    stripped = line.strip()
    if stripped == "" or stripped == ":vars":
        if stripped == ":vars":
            for name in sorted(env):
                print(f"{name} = {format_value(env[name])}")
        return
    split = _split_assignment(line)
    if split is not None:
        left, right = split
        name = left.strip()
        if _IDENT_RE.fullmatch(name) and name not in _KEYWORDS:
            try:
                value = evaluate(right, env)
            except MiniLangError as exc:
                print(f"error: {exc}")
